uint32_t lb_sema_types_u32_id = 12ULL;
uint32_t lb_sema_types_u64_id = 13ULL;
uint32_t lb_sema_types_usize_id = 14ULL;
uint32_t lb_sema_types_f32_id = 15ULL;
uint32_t lb_sema_types_f64_id = 16ULL;
uint32_t lb_sema_types_char_id = 17ULL;
uint32_t lb_sema_types_str_id = 18ULL;
uint32_t lb_sema_types_cstr_id = 19ULL;
uint32_t lb_sema_types_fmt_id = 20ULL;
uint32_t lb_sema_types_void_id = 21ULL;
uint32_t lb_sema_types_untyped_int_id = 22ULL;
uint32_t lb_sema_types_untyped_float_id = 23ULL;
uint32_t lb_sema_types_error_code_id = 24ULL;
uint32_t lb_sema_types_error_value_id = 25ULL;
